package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import jdistlib.ChiSquare;
import org.jlinalg.mr.SmrStatistics;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
import static org.jlinalg.cli.SmrWorkflowInputs.*;

/** Independent complete-family/ratio audit. HEIDI and multi-SNP tail fitting remain original SMR. */
final class SmrWorkflowAudit {
    private SmrWorkflowAudit() { }
    record Aligned(Variant variant,Gwas gwas,Reference reference,double by,double gyFrequency,double referenceFrequency,String disposition) { }
    record Expected(Probe probe,Entry top,Aligned aligned,int eligible,int nullSnps,double theta,String disposition) { }
    static Map<String,Object> analysis(Path home,Map<String,Object> a,Population p,SmrWorkflowRequest.Request r,Budget budget,List<String> warnings)throws IOException {
        String id=text(a.get("id"));boolean multi=a.get("kind").equals("multi"),useReference=multi||!object(a.get("heidi")).get("method").equals("off");var aligned=alignment(home,a,p,r,useReference,budget);var expected=new LinkedHashMap<String,Expected>();var variants=new HashMap<String,Variant>();for(Variant v:p.qtl().variants())variants.put(v.id(),v);
        var overlap=object(a.get("sample_overlap"));boolean estimate=overlap.get("kind").equals("estimate-original");double cutoff=estimate?Math.sqrt(ChiSquare.quantile(finite(overlap.get("null_p"),0,1),1,false,false)):0;long cisWindow=integer(a.get("window_kb"),1,2000000);if(multi)cisWindow=Math.max(cisWindow,integer(object(a.get("multi")).get("window_kb"),1,2000000));var denseOrder=new HashMap<String,Integer>();if(useReference&&(p.qtl().type()==0||p.qtl().type()==5)){int rank=0;for(String snp:p.reference().keySet())denseOrder.put(snp,rank++);}
        try(var ledger=Files.newBufferedWriter(home.resolve("native-observation-ledger.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
            ledger.write("probe\tsnp\tdisposition\tbeta_binary32\tse_binary32\n");
            for(Probe probe:p.qtl().probes()){
                Entry top=null;double topZ=0;int count=0;var zx=new ArrayList<Double>();var zy=new ArrayList<Double>();
                List<Entry> ordered=p.qtl().entries().getOrDefault(probe.id(),List.of());if(!denseOrder.isEmpty()){budget.add((long)ordered.size()*Math.max(1,32-Integer.numberOfLeadingZeros(ordered.size())));var sorted=new ArrayList<>(ordered);sorted.sort(Comparator.comparingInt(e->denseOrder.getOrDefault(e.snp(),Integer.MAX_VALUE)));ordered=sorted;}
                for(Entry e:ordered){budget.add(1);Variant v=variants.get(e.snp());Aligned al=aligned.get(e.snp());String disposition=!p.probes().contains(probe.id())?"probe-not-requested":e.missing()?"source-dense-missing":!al.disposition().equals("eligible")?al.disposition():v.chr()!=probe.chr()||Math.abs((long)v.bp()-probe.bp())>1000L*cisWindow?"outside-cis-window":"eligible";
                    if(disposition.equals("eligible")){double z=(double)e.beta()/e.se(),y=al.by()/al.gwas().se();require(Double.isFinite(z)&&Double.isFinite(y),"Unrepresentable source input Z; no omission");count++;if(top==null||topZ-Math.abs(z)<1e-6){top=e;topZ=Math.abs(z);}if(estimate&&Math.abs(z)<cutoff&&Math.abs(y)<cutoff){zx.add(z);zy.add(y);}}
                    ledger.write(probe.id()+"\t"+e.snp()+"\t"+disposition+"\t"+e.beta()+"\t"+e.se()+"\n");
                }
                String disposition=!p.probes().contains(probe.id())?"probe-not-requested":top==null?"no-eligible-cis-QTL":estimate&&zx.size()<integer(overlap.get("minimum_null_snps"),2,1000000)?"insufficient-source-null-SNPs":"eligible";double theta=0;
                if(disposition.equals("eligible")&&estimate)theta=correlation(zx,zy);
                if(disposition.equals("eligible")&&tail((double)top.beta()/top.se())>finite(a.get("qtl_p"),0,1))disposition="top-QTL-above-threshold";
                expected.put(probe.id(),new Expected(probe,top,top==null?null:aligned.get(top.snp()),count,zx.size(),theta,disposition));
            }
        }
        String suffix=multi?".msmr":".smr";var rows=table(home.resolve("original"+suffix),multi?22:21,r.probesLimit()+1L,r);var names=new ArrayList<>(List.of("probeID","ProbeChr","Gene","Probe_bp","topSNP","topSNP_chr","topSNP_bp","A1","A2","Freq","b_GWAS","se_GWAS","p_GWAS","b_eQTL","se_eQTL","p_eQTL","b_SMR","se_SMR","p_SMR"));if(multi)names.add("p_SMR_multi");names.addAll(List.of("p_HEIDI","nsnp_HEIDI"));header(rows,names.toArray(String[]::new));var seen=new LinkedHashSet<String>();int unavailable=0;
        try(var ratios=Files.newBufferedWriter(home.resolve("native-ratio-ledger.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);var kinds=Files.newBufferedWriter(home.resolve("original-probability-kinds.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
        ratios.write("probe\teffect\tSE\tchi_square\tP\tlog_P\terror_correlation_value\tcorrelation_applied_to_ratio\n");kinds.write("probe\tfield\toriginal_token\tnumeric_kind\n");
        for(int i=1;i<rows.size();i++){budget.add(1);String[] x=rows.get(i);Expected e=expected.get(x[0]);require(e!=null&&e.disposition().equals("eligible")&&seen.add(x[0]),"Original returned an extra, duplicate or ineligible probe: "+x[0]);Variant v=e.aligned().variant();require(x[1].equals(Integer.toString(e.probe().chr()))&&x[2].equals(e.probe().gene())&&x[3].equals(Integer.toString(e.probe().bp()))&&x[4].equals(e.top().snp())&&x[5].equals(Integer.toString(v.chr()))&&x[6].equals(Integer.toString(v.bp()))&&x[7].equals(v.a1())&&x[8].equals(v.a2()),"Original top SNP/probe/allele identity differs");
            check(x[9],useReference?e.aligned().referenceFrequency():(double)(float)v.frequency(),6,"output frequency");check(x[10],e.aligned().by(),6,"aligned GWAS beta");check(x[11],e.aligned().gwas().se(),6,"GWAS SE");check(x[12],multi?tail(e.aligned().by()/e.aligned().gwas().se()):e.aligned().gwas().p()==null?0:e.aligned().gwas().p(),7,"GWAS P");check(x[13],e.top().beta(),6,"QTL binary32 beta");check(x[14],e.top().se(),6,"QTL binary32 SE");check(x[15],tail((double)e.top().beta()/e.top().se()),7,"QTL P");
            var ratio=SmrStatistics.ratio(e.top().beta(),e.top().se(),e.aligned().by(),e.aligned().gwas().se(),multi?0:e.theta());check(x[16],ratio.effect(),6,"SMR effect");check(x[17],ratio.standardError(),6,"SMR SE");check(x[18],ratio.pValue(),7,"SMR P");
            ratios.write(x[0]+"\t"+ratio.effect()+"\t"+ratio.standardError()+"\t"+ratio.statistic()+"\t"+ratio.pValue()+"\t"+ratio.logPValue()+"\t"+e.theta()+"\t"+(multi?0:e.theta())+"\n");int h=multi?20:19;if(multi)sourceProbability(x[19],"multi-SNP original P");String hp=x[h],hn=x[h+1];sourceProbability(hp,"original HEIDI P");if(!hn.equals("NA"))require(position(hn)>=2,"Invalid original HEIDI instrument count");if(object(a.get("heidi")).get("method").equals("off"))require(hp.equals("NA")&&hn.equals("NA"),"HEIDI-off unexpectedly reports HEIDI results");if(hp.equals("NA")||hn.equals("NA"))unavailable++;
            var probabilityColumns=new ArrayList<>(List.of(12,15,18));if(multi)probabilityColumns.add(19);probabilityColumns.add(h);for(int column:probabilityColumns){String kind=Set.of("NA","nan","-nan","NaN","inf","-inf","Inf","-Inf").contains(x[column])?x[column]:number(x[column])==0?"displayed-zero-or-underflow":"finite";kinds.write(x[0]+"\t"+names.get(column)+"\t"+x[column]+"\t"+kind+"\n");if(!kind.equals("NA")&&!kind.equals("finite")&&!kind.equals("displayed-zero-or-underflow"))warnings.add("ORIGINAL NONFINITE ["+id+" / "+x[0]+" / "+names.get(column)+"]: literal "+x[column]+" retained; no replacement or independent tail estimate.");}
        }
        }
        var expectedOrder=new ArrayList<String>();for(Expected e:expected.values())if(e.disposition().equals("eligible"))expectedOrder.add(e.probe().id());require(new ArrayList<>(seen).equals(expectedOrder),"Complete original output probe order differs from source EPI order");
        try(var ledger=Files.newBufferedWriter(home.resolve("native-probe-ledger.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
            ledger.write("probe\tdisposition\teligible_cis_QTLs\tnull_SNPs\terror_correlation_value\ttop_SNP\n");for(Expected e:expected.values()){require(seen.contains(e.probe().id())==e.disposition().equals("eligible"),"Complete original probe family differs for "+e.probe().id()+"; inspect native and original ledgers, no result admitted");ledger.write(e.probe().id()+"\t"+(seen.contains(e.probe().id())?"original-row-audited":e.disposition())+"\t"+e.eligible()+"\t"+(estimate?e.nullSnps():"NA")+"\t"+e.theta()+"\t"+(e.top()==null?"NA":e.top().snp())+"\n");}
        }
        if(multi)multiAuxiliary(home,seen,expected,variants,a,r,budget);
        long coordinateDifferences=aligned.values().stream().filter(al->useReference&&al.reference()!=null&&(al.variant().chr()!=al.reference().variant().chr()||al.variant().bp()!=al.reference().variant().bp())).count();if(coordinateDifferences>0)warnings.add("REFERENCE COORDINATE DISAGREEMENT ["+id+"]: "+coordinateDifferences+" reference/QTL SNP coordinates differ under the explicit source-ID-and-alleles-with-ledger policy. Original ID matching was retained; no liftover or assembly validation occurred. Inspect native-variant-ledger.tsv.");if(seen.isEmpty())warnings.add("NO OUTPUT PROBES ["+id+"]: the complete declared source filter family returned zero rows. Inspect every native-probe-ledger.tsv disposition; this is no positive or negative association finding.");
        if(unavailable>0)warnings.add("ORIGINAL HEIDI UNAVAILABLE ["+id+"]: "+unavailable+" rows retain original NA P/count fields. HEIDI off, skip thresholds, too few eligible instruments and numerical outcomes remain distinct in the request and original logs; NA is not evidence of homogeneity.");
        if(overlap.get("kind").equals("source-flag-without-estimation"))warnings.add("ORIGINAL MULTI-SNP OVERLAP FLAG WITHOUT ESTIMATION ["+id+"]: both selected source entry paths leave theta0, skip null-SNP correlation estimation/filtering, print the ratio SE without overlap correction and pass the literal flag with theta0 to HEIDI. This explicitly requested source behavior is retained; it is not an estimated overlap correction. No null-P/minimum-null-SNP options were passed.");
        var report=new LinkedHashMap<String,Object>();report.put("id",id);report.put("original_rows",seen.size());report.put("complete_probe_axis",expected.size());report.put("native_complete_family_and_ratio_checked",true);report.put("original_heidi_and_multi_tail_independently_refitted",false);report.put("original_unavailable_heidi_rows",unavailable);report.put("actual_reference_used",useReference);report.put("sample_overlap_mode",overlap.get("kind"));report.put("error_correlation_estimated",estimate);NextflowFiles.writeJson(home.resolve("native-audit.json"),report);return report;
    }
    private static Map<String,Aligned> alignment(Path home,Map<String,Object> a,Population p,SmrWorkflowRequest.Request r,boolean ref,Budget budget)throws IOException {
        var result=new LinkedHashMap<String,Aligned>();var f=object(a.get("frequency_check"));int before=0,failed=0;
        try(var out=Files.newBufferedWriter(home.resolve("native-variant-ledger.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
            out.write("snp\tdisposition\tGWAS_swapped_to_QTL\treference_swapped_to_QTL\tGWAS_frequency_aligned\tQTL_frequency_binary32\treference_frequency_aligned\traw_called\traw_missing\traw_dosage_variance\tcoordinate_agreement\n");
            for(Variant v:p.qtl().variants()){budget.add(1);Gwas g=p.gwas().get(v.id());Reference b=p.reference().get(v.id());int gs=g==null?0:sign(v.a1(),v.a2(),g.a1(),g.a2()),bs=b==null?0:sign(v.a1(),v.a2(),b.variant().a1(),b.variant().a2());double by=g==null?0:gs*g.beta(),gf=g==null?-9:gs<0&&g.frequency()>0?1-g.frequency():g.frequency(),bf=b==null?-9:bs<0?b.otherAlleleFrequency():b.frequency(),ef=(double)(float)v.frequency();boolean coordinates=b!=null&&v.chr()==b.variant().chr()&&v.bp()==b.variant().bp();
                String why=g==null?"absent-GWAS":gs==0?"GWAS-allele-mismatch":ref&&b==null?"absent-LD-reference":ref&&bs==0?"reference-allele-mismatch":"eligible";
                if(ref&&why.equals("eligible")&&!coordinates){require(!r.reference().get("coordinate_policy").equals("require-equal"),"Reference/QTL coordinates differ for "+v.id()+"; no inferred liftover");}
                double maf=finite(a.get("minimum_maf"),0,.5);if(ref&&why.equals("eligible")&&maf>0&&(bf<=maf||1-bf<=maf))why="source-strict-MAF-excluded";
                if(why.equals("eligible")){before++;if(f.get("kind").equals("source-check")){double diff=finite(f.get("maximum_difference"),0,1);boolean fail=gf>0&&ef>0&&Math.abs(gf-ef)>diff;if(ref){if(gf<0&&ef>0)fail=Math.abs(bf-ef)>diff;else if(gf>0&&ef<0)fail=Math.abs(bf-gf)>diff;else if(gf>0&&ef>0)fail|=Math.abs(bf-gf)>diff||Math.abs(bf-ef)>diff;}if(fail){why="source-frequency-excluded";failed++;}}}
                result.put(v.id(),new Aligned(v,g,b,by,gf,bf,why));out.write(v.id()+"\t"+why+"\t"+(gs<0)+"\t"+(bs<0)+"\t"+gf+"\t"+ef+"\t"+bf+"\t"+(b==null?"NA":b.called())+"\t"+(b==null?"NA":b.missing())+"\t"+(b==null?"NA":b.variance())+"\t"+(b==null?"not-applicable":coordinates)+"\n");
            }
            for(Gwas g:p.gwas().values())if(!result.containsKey(g.id()))out.write(g.id()+"\tabsent-QTL-axis\tNA\tNA\t"+g.frequency()+"\tNA\tNA\tNA\tNA\tNA\tnot-applicable\n");
        }
        require(before>failed,"No source-aligned SNP remains");if(f.get("kind").equals("source-check"))require((double)failed/before<=finite(f.get("maximum_excluded_fraction"),0,1),"Original frequency-exclusion proportion exceeds declared maximum");
        Path check=home.resolve("original.snp_failed_freq_ck.list");if(f.get("kind").equals("disabled"))require(!Files.exists(check),"Original frequency check was not disabled");else{var rows=table(check,ref?5:4,r.variants()+1L,r);var actual=new HashSet<String>();for(int i=1;i<rows.size();i++)require(actual.add(rows.get(i)[0]),"Duplicate original frequency failure");var wanted=new HashSet<String>();for(var e:result.values())if(e.disposition().equals("source-frequency-excluded"))wanted.add(e.variant().id());require(actual.equals(wanted),"Complete original frequency-exclusion family differs");}return result;
    }
    private static void multiAuxiliary(Path home,Set<String> probes,Map<String,Expected> expected,Map<String,Variant> variants,Map<String,Object> a,SmrWorkflowRequest.Request r,Budget budget)throws IOException {
        Path sets=home.resolve("original.snps4msmr.list");require(Files.exists(sets),"Original multi-SNP selected-instrument list absent");if(probes.isEmpty()){require(Files.size(sets)==0&&Files.isRegularFile(home.resolve("original.prbregion4msmr.list"))&&Files.size(home.resolve("original.prbregion4msmr.list"))==0,"Original empty multi-SNP output has nonempty/missing auxiliary families");return;}var rows=table(sets,1,Math.min(r.nativeOperations(),Integer.MAX_VALUE),r);var seen=new LinkedHashSet<String>();int i=0;while(i<rows.size()){String probe=rows.get(i++)[0];require(probes.contains(probe)&&seen.add(probe),"Original multi-SNP list gene family differs");var ids=new HashSet<String>();boolean end=false;while(i<rows.size()){budget.add(1);String snp=rows.get(i++)[0];if(snp.equals("end")){end=true;break;}Variant v=variants.get(snp);Expected e=expected.get(probe);require(v!=null&&ids.add(snp)&&v.chr()==e.probe().chr()&&Math.abs((long)v.bp()-e.aligned().variant().bp())<=1000L*integer(object(a.get("multi")).get("window_kb"),1,2000000),"Original multi-SNP instrument identity/window differs");}require(end&&!ids.isEmpty(),"Original multi-SNP instrument list incomplete");}require(seen.equals(probes),"Original multi-SNP list omits output genes");
    }
    private static int sign(String a,String b,String c,String d){return a.equals(c)&&b.equals(d)?1:a.equals(d)&&b.equals(c)?-1:0;}
    private static double tail(double z)throws IOException {double p=ChiSquare.cumulative(z*z,1,false,false);require(Double.isFinite(p),"Native input tail unrepresentable");return p;}
    private static double correlation(List<Double> x,List<Double> y)throws IOException {double mx=0,my=0;for(int i=0;i<x.size();i++){mx+=x.get(i);my+=y.get(i);}mx/=x.size();my/=y.size();double xx=0,yy=0,xy=0;for(int i=0;i<x.size();i++){double a=x.get(i)-mx,b=y.get(i)-my;xx+=a*a;yy+=b*b;xy+=a*b;}double value=xx>0&&yy>0?xy/Math.sqrt(xx*yy):0;require(Double.isFinite(value)&&Math.abs(value)<=1,"Original null-SNP correlation is outside native audit domain; no fallback");return value;}
    private static void check(String token,double full,int digits,String field)throws IOException {rounded(number(token),full,digits,field);}
    private static void sourceProbability(String token,String field)throws IOException {if(!Set.of("NA","nan","-nan","NaN","inf","-inf","Inf","-Inf").contains(token))probability(token);}
}
